import 'package:flutter/material.dart';
import 'package:work_key/shared/components/components.dart';
import 'package:work_key/utils/constants.dart';

class ActivityLoadingState extends StatelessWidget { const ActivityLoadingState({super.key}); @override Widget build(BuildContext context) => Column(children: List.generate(4, (_) => Padding(padding: const EdgeInsets.only(bottom: 12), child: Container(height: 150, decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(20)))))); }
class ActivityEmptyState extends StatelessWidget { final String message; const ActivityEmptyState({super.key, required this.message}); @override Widget build(BuildContext context) => Padding(padding: const EdgeInsets.symmetric(vertical: 65), child: Column(children: [const Icon(Icons.notifications_none_rounded, size: 58, color: HomeColors.muted), const SizedBox(height: 13), DefaultText(text: message, textAlign: TextAlign.center, style: const TextStyle(color: HomeColors.ink, fontSize: 16, fontWeight: FontWeight.w800))])); }
class ActivityErrorState extends StatelessWidget { final String message; final VoidCallback retry; const ActivityErrorState({super.key, required this.message, required this.retry}); @override Widget build(BuildContext context) => Padding(padding: const EdgeInsets.symmetric(vertical: 65), child: Column(children: [const Icon(Icons.cloud_off_rounded, size: 55, color: HomeColors.muted), const SizedBox(height: 12), DefaultText(text: message, textAlign: TextAlign.center, style: const TextStyle(color: HomeColors.ink)), const SizedBox(height: 16), DefaultButton(width: 150, background: HomeColors.purple, text: 'Try again', uppercase: false, onPress: retry)])); }
